  &lt;id&gt;82616&lt;&#x2F;id&gt;
  &lt;imdbid&gt;tt0983200&lt;&#x2F;imdbid&gt;
  &lt;tmdbid&gt;328&lt;&#x2F;tmdbid&gt;
  &lt;uniqueid default=&quot;false&quot; type=&quot;tmdb&quot;&gt;328&lt;&#x2F;uniqueid&gt;
  &lt;uniqueid default=&quot;false&quot; type=&quot;imdb&quot;&gt;tt0983200&lt;&#x2F;uniqueid&gt;
